steps.demo:
{{pins}}
#include <Servo.h>

Servo lid;

// Grove Ultrasonic Ranger: one pin sends a click, then listens for its echo.
long readCm(int pin) {
  pinMode(pin, OUTPUT);
  digitalWrite(pin, LOW);
  delayMicroseconds(2);
  digitalWrite(pin, HIGH);
  delayMicroseconds(5);
  digitalWrite(pin, LOW);
  pinMode(pin, INPUT);
  long us = pulseIn(pin, HIGH, 30000UL);
  return us / 58;
}

void setup() {
  lid.attach(SERVO_PIN);
  lid.write(0);
  pinMode(LED_PIN, OUTPUT);
  pinMode(SWITCH_PIN, INPUT);
  Serial.begin(9600);
}

void loop() {
  long cm = readCm(RANGER_PIN);
  if (cm > 0 && cm < 15) {
    lid.write(90);
    digitalWrite(LED_PIN, HIGH);
    Serial.println("open");
    delay(3000);
    lid.write(0);
    unsigned long start = millis();
    while (digitalRead(SWITCH_PIN) == LOW && millis() - start < 2000) {
      delay(10);  // wait for the lid to press the micro switch
    }
    if (digitalRead(SWITCH_PIN) == HIGH) {
      Serial.println("closed");
      digitalWrite(LED_PIN, LOW);
    } else {
      Serial.println("lid stuck!");
    }
  }
  delay(100);
}
